const r=[{id:"F01",title:"Sahih al-Bukhari 1 · Actes et intentions",url:"https://sunnah.com/bukhari:1",type:"religious",finding:"Umar ibn al-Khattab rapporte l’enseignement du Prophète sur les actes et les intentions.",limitation:"Source religieuse, pas étude empirique. L’exercice quotidien d’ODA est une interprétation, pas le texte du hadith ni un avis religieux. Une application ne peut juger ni la sincérité ni la récompense divine."},{id:"F02",title:"Sahih al-Bukhari 6491 · Actes envisagés et accomplis",url:"https://sunnah.com/bukhari:6491",type:"religious",finding:"Le passage rapporté par Ibn Abbas décrit comment sont consignés les bons et mauvais actes envisagés ou accomplis.",limitation:"Ces précisions théologiques ne sont pas une loi psychologique. Les notes de préparation et d’action d’ODA décrivent un comportement ; elles ne peuvent déterminer une récompense religieuse."},{id:"F03",title:"Le Coran · Al Imran 3:159",url:"https://quran.com/3/159",type:"religious",finding:"Ce verset réunit la consultation, la résolution et la confiance en Dieu.",limitation:"ODA en tire une réflexion pratique facultative. Elle ne fixe pas un ordre universel où la confiance commencerait seulement après la préparation. Elle ne propose ni interprétation exhaustive ni résultat garanti."},{id:"F07",title:"Sunan Abi Dawud 4811 · Remercier les autres",url:"https://sunnah.com/abudawud:4811",type:"religious",finding:"L’enseignement rapporté par Abu Hurayrah relie le remerciement des autres à celui d’Allah. La fiche affiche une classification sahih attribuée à al-Albani.",limitation:"Enseignement religieux, pas preuve d’efficacité psychologique. Le modèle de remerciement est une adaptation d’ODA. Vérifier la source ne constitue ni une nouvelle authentification ni une obligation de prendre contact au risque de sa sécurité."},{id:"F08",title:"Le Coran · Al-Sharh 94:5–6",url:"https://quran.com/94/5-6",type:"religious",finding:"L’évocation d’une facilité aux côtés de l’épreuve offre une source d’espoir religieux.",limitation:"Rien ne garantit qu’une difficulté personnelle finira aujourd’hui ou à une date choisie. La demande de soutien d’ODA est une adaptation, pas un effet clinique ni une interprétation exhaustive."},{id:"F11",title:"Sahih al-Bukhari 6464 · Petits actes réguliers et modération",url:"https://sunnah.com/bukhari:6464",type:"religious",finding:"Aïcha rapporte un enseignement qui souligne les petits actes réguliers et la modération.",limitation:"Le passage complet concerne aussi les actes et le salut. Une série de jours dans une application ne mesure ni la foi ni le salut. L’aide avec une limite de temps est une adaptation d’ODA."},{id:"F13",title:"Ano et Vasconcelles · 2005 · Recours à la religion et adaptation",url:"https://mhwbf.org/wp-content/uploads/2019/02/Ano-2005-Religious-coping-and-psychological-ad.pdf",type:"research",finding:"Dans 49 études surtout observationnelles, le recours à la religion était associé à l’adaptation. Au tableau 5, les valeurs z de Fisher combinées étaient de .33 [.30, .35] pour recours positif/adaptation positive, et de .22 [.19, .24] pour recours négatif/adaptation négative.",limitation:"Ce ne sont ni des corrélations brutes ni des preuves de causalité. Parmi 8 115 personnes d’affiliation connue, 57 % étaient protestantes et 28 % catholiques. Facteurs de confusion, autodéclarations et portée limitée pour l’islam subsistent. Ces catégories ne jugent pas l’apprenant."},{id:"F14",title:"Kirca et al. · 2023 · Gratitude exprimée et bien-être",url:"https://doi.org/10.1007/s41042-023-00086-6",type:"research",finding:"Sur 23 études et 25 échantillons, exprimer sa gratitude avait un petit bénéfice moyen pour le bien-être face aux comparaisons neutres : g = .22, IC à 95 % [.11, .33]. Face à d’autres activités de bien-être : g = .12 [−.02, .26].",limitation:"Ni supériorité démontrée sur les comparaisons actives ni équivalence à une thérapie. Échantillons surtout non cliniques. Les totaux de participants divergent dans l’article : aucun n’est repris. Ni efficacité religieuse, ni contact imposé, ni bénéfice personnel garanti."},{id:"F15",title:"Choi et al. · 2025 · Gratitude dans différentes cultures",url:"https://www.pnas.org/doi/10.1073/pnas.2425193122",type:"research",finding:"Sur 145 articles et 163 échantillons dans 28 pays, les exercices de gratitude avaient un petit effet moyen sur le bien-être : g = .19, IC à 95 % [.15, .22]. L’intervalle de prédiction pour une future étude était [−.21, .59].",limitation:"Échantillons surtout non cliniques, méthodes variées. Les effets diffèrent ; l’intervalle de prédiction inclut zéro. Cela ne valide pas une phrase privée, ne prédit pas la réaction individuelle et ne démontre pas une supériorité de la gratitude islamique."},{id:"F16",title:"Curry et al. · 2018 · Bienveillance et bien-être de celui qui aide",url:"https://research-portal.uu.nl/ws/portalfiles/portal/247379826/1-s2.0-S0022103117303451-main.pdf",type:"research",finding:"Sur 27 études et 4 045 participants, les gestes bienveillants montraient un bénéfice moyen modeste pour celui qui aide : δ = .28, IC à 95 % [.16, .41].",limitation:"Études hétérogènes, surtout non cliniques. Ni bénéfice garanti pour chacun, ni effet thérapeutique, ni mesure d’une récompense religieuse. Aucun soutien au sacrifice sans limites. Ne pas détecter un biais ou un facteur modérateur ne prouve pas son absence."},{id:"F18",title:"Nelson et al. · 2016 · Essai sur l’aide aux autres",url:"https://sonjalyubomirsky.com/wp-content/uploads/2024/03/Nelson-Layous-Cole-Lyubomirsky-2016.pdf",type:"research",finding:"Le groupe d’aide aux autres devait accomplir trois gestes bienveillants le même jour, chaque semaine pendant quatre semaines, puis être évalué deux semaines après. L’estimation combinée de l’évolution de l’épanouissement, face au groupe témoin, était d = .31, p = .05.",limitation:"L’effectif du résumé diffère du total réparti aléatoirement : 473 contre 472, dont 464 dans les analyses d’évolution. Intervalle de confiance et préenregistrement non vérifiés. Le geste unique d’ODA diffère de l’essai et ne promet pas un bénéfice universel."},{id:"F19",title:"Wang et al. · 2021 · Plans face aux obstacles et objectifs",url:"https://www.frontiersin.org/journals/psychology/articles/10.3389/fpsyg.2021.565202/full",type:"research",finding:"Dans 21 articles et 24 effets indépendants portant sur 15 907 participants, confronter un objectif à ses obstacles puis prévoir « si… alors… » aidait en moyenne à l’atteindre : g = .336, IC à 95 % [.229, .443].",limitation:"Objectifs et méthodes variés ; la correction du biais de publication réduit l’estimation. Cela ne valide ni l’intention sincère seule, ni la prière comme cause de réussite, ni une liste propre à la foi, ni dix minutes comme durée optimale."},{id:"F20",title:"NIMH · 2026 · Prendre soin de sa santé mentale",url:"https://www.nimh.nih.gov/health/topics/caring-for-your-mental-health",type:"guidance",finding:"Une détresse persistante et des difficultés dans les activités habituelles justifient un soutien professionnel. Une crise demande une aide immédiate.",limitation:"Conseils au public, pas diagnostic ni preuve d’une cause spirituelle. Nul besoin d’attendre deux semaines ou de finir un cours pour demander de l’aide. Prière et conseil spirituel ne remplacent pas les soins."},{id:"faith-kindness",title:"Curry et al. · 2018 · Bienveillance et bien-être de celui qui aide",url:"https://research-portal.uu.nl/ws/portalfiles/portal/247379826/1-s2.0-S0022103117303451-main.pdf",type:"research",finding:"Sur 27 études et 4 045 participants, les gestes bienveillants montraient un bénéfice moyen modeste pour celui qui aide : δ = .28, IC à 95 % [.16, .41].",limitation:"Études hétérogènes, surtout non cliniques. Ni bénéfice garanti pour chacun, ni effet thérapeutique, ni mesure d’une récompense religieuse. Aucun soutien au sacrifice sans limites. Ne pas détecter un biais ou un facteur modérateur ne prouve pas son absence."}],i=[{schemaVersion:2,revision:2,id:"faith-1",courseId:"faith",locale:"fr",title:"Ta bonne intention attend encore",goal:"Accomplis une partie utile d’une promesse qui exprime la valeur que tu as choisie.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Tu voulais aider. Aujourd’hui, fais quelque chose de concret pour tenir cette promesse.",reason:{id:"faith-1-purpose-cost",label:"Que ferais-tu même sans recevoir de compliments ?",kind:"text",maxLength:160,optional:!0,suggestions:["Tenir ma promesse du quotidien","Aider en respectant mes limites","Agir selon la valeur choisie"]},why:{id:"faith-1-why",label:"Que ferais-tu même sans recevoir de compliments ?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Le premier hadith de Bukhari concerne actes et intentions. Umar rapporte l’enseignement du Prophète. Cet exercice quotidien est une interprétation d’ODA. Choisis une promesse. Ce qui compte doit guider un geste utile ; l’application ne juge pas tes motivations.","Tu peux vouloir aider et être reconnu. Pas de pureté à prouver ici. Choisis ton intention, puis accomplis une partie convenue. Si agir est impossible, préparer reste préparer. Tu peux garder ta réflexion spirituelle hors d’ODA. Les réponses facultatives sont enregistrées dans la leçon ou le plan ; les partager avec le coach demande un accord distinct."],example:{title:"Youssef tient une petite promesse",text:"Youssef a promis à sa voisine un guide simple pour son téléphone. À midi, il veut aider et paraître fiable. Il choisit d’aider et envoie les étapes convenues pour passer un appel. Sa voisine ne répond pas cet après-midi. Il note le message envoyé, garde ses motivations privées et ignore encore si cela a aidé."}},move:{invitation:"Fais un geste utile pour tenir ta promesse. Adapte l’exemple à votre accord réel.",instructions:["Précise quoi, pour quelle personne sûre, comment et quand. Tu peux garder cela privé.","Respecte votre accord : envoyer est l’action ; rédiger seulement reste une préparation."],prompts:[],suggestions:{action:["Exemple : envoyer à Camille le lien convenu","Laver les deux mugs promis à Youssef","Envoyer à Alex le trajet convenu du rendez-vous"],minimum:["Envoyer le lien convenu pour régler son téléphone","Laver les deux mugs convenus","Envoyer le trajet convenu jusqu’à l’arrêt de bus"],cue:["Après mon déjeuner","À la fin de notre repas partagé","Quand arrive le rappel du rendez-vous d’Alex"],place:["Dans notre conversation par SMS","À l’évier que nous pouvons utiliser","Dans notre conversation habituelle"],minutes:[2,1],fallback:["Utiliser le mail convenu si le SMS échoue","Convenir d’un autre nettoyage utile et accessible","Utiliser notre moyen de contact convenu et accessible"],observation:["Lien envoyé ; utilité et réponse encore inconnues","Tâche promise accomplie, pas seulement préparée","Trajet envoyé ; une réponse reste incertaine"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}],bundles:[{action:"Exemple : envoyer à Camille le lien convenu",minimum:"Envoyer le lien convenu pour régler son téléphone",cue:"Après mon déjeuner",place:"Dans notre conversation par SMS",fallback:"Utiliser le mail convenu si le SMS échoue",observation:"Lien envoyé ; utilité et réponse encore inconnues",minutes:2},{action:"Laver les deux mugs promis à Youssef",minimum:"Laver les deux mugs convenus",cue:"À la fin de notre repas partagé",place:"À l’évier que nous pouvons utiliser",fallback:"Convenir d’un autre nettoyage utile et accessible",observation:"Tâche promise accomplie, pas seulement préparée",minutes:1},{action:"Envoyer à Alex le trajet convenu du rendez-vous",minimum:"Envoyer le trajet convenu jusqu’à l’arrêt de bus",cue:"Quand arrive le rappel du rendez-vous d’Alex",place:"Dans notre conversation habituelle",fallback:"Utiliser notre moyen de contact convenu et accessible",observation:"Trajet envoyé ; une réponse reste incertaine",minutes:2}]},suggested:{action:"Exemple : envoyer à Camille le lien convenu",minimum:"Envoyer le lien convenu pour régler son téléphone",minutes:2,cueHint:"Après mon déjeuner",placeHint:"Dans notre conversation par SMS",obstacleHint:"Exemple : expliquer mes motivations au lieu d’envoyer",fallbackHint:"Utiliser le mail convenu si le SMS échoue",observationHint:"Lien envoyé ; utilité et réponse encore inconnues"},stopRule:"Choisis seulement des gestes sûrs, volontaires et compatibles avec tes limites.",accessibleAlternative:"Utilise ton moyen de communication habituel ; garde ton plan hors d’ODA."},result:{question:"As-tu réellement accompli le geste utile que tu avais choisi ?",observationPrompt:"Qu’as-tu fait, sans dévoiler tes motivations privées ?"},judgment:{primary:{id:"faith-1-decision",scenario:"Youssef a promis des notes utiles à un camarade. Elles sont prêtes. Il veut aider et être reconnu. Son camarade souhaite les recevoir et l’envoi est sans risque.",question:"Quel choix permet de tenir la promesse convenue ?",options:[{id:"private-reflection",text:"Réfléchir en privé à ses motivations une journée de plus avant de décider s’il envoie les notes prêtes.",feedback:"Réfléchir en privé peut être utile. Ici, les notes convenues sont prêtes et l’envoi est sûr. Attendre une intention plus pure retarde l’aide. Il peut réfléchir sans exiger cette pureté."},{id:"send-agreed-notes",text:"Choisir d’aider et envoyer les notes convenues sans faire des compliments une condition.",feedback:"Ce choix tient la promesse et laisse coexister plusieurs motivations. On note l’envoi des notes, sans prétendre prouver la sincérité. La réponse du camarade et le bénéfice restent à observer séparément."},{id:"explain-intention",text:"Expliquer d’abord ses intentions au camarade, puis proposer d’envoyer les notes une fois qu’il aura répondu.",feedback:"Expliquer peut sembler honnête. Mais cela demande au camarade de s’occuper de ses motivations avant de recevoir l’aide convenue. Il peut garder sa réflexion privée et envoyer directement les notes utiles."}],bestOptionId:"send-agreed-notes"}},carry:{takeaway:"Agis pour ce qui compte. Ton intention privée reste à toi.",followUp:{questionId:"faith-1-return",question:"Le geste a-t-il servi ton intention, ou était-ce une préparation ?",observationPrompt:"Qu’as-tu fait, sans dévoiler tes motivations privées ?",adjustmentPrompt:"Que changer pour que le prochain essai te convienne ?"}},goDeeper:{sections:[{heading:"Le sens religieux ne se mesure pas dans l’application",paragraphs:["Dans Sahih al-Bukhari 1, Umar ibn al-Khattab rapporte l’enseignement du Prophète sur les actes et les intentions. L’exercice d’ODA te propose de voir comment ce qui compte pour toi peut guider une promesse du quotidien. C’est une interprétation pédagogique, pas le texte du hadith, une explication exhaustive ou un avis religieux. [F01] Tu peux réfléchir en privé sans écrire ta motivation.","Bukhari 6491 décrit les actes envisagés et accomplis dans un récit théologique de leur consignation. Un journal d’actions ne peut réduire ce récit à un score ni déterminer une récompense divine. [F02] « Instructions préparées » et « instructions convenues envoyées » décrivent deux comportements différents. Aucun ne dit à ODA si tu étais sincère. Un plan, une réponse au quiz, une série de jours ou une pause ne permettent pas de juger la foi. Si agir est impossible, tu peux choisir une préparation et, si utile, préciser quand tu pourras la mettre en pratique."]},{heading:"Prévoir quand agir donne une place à ton intention",paragraphs:["Une synthèse a réuni 21 articles et 24 effets indépendants. Confronter le but souhaité à un obstacle réel puis prévoir quoi faire face à cet obstacle aidait, en moyenne, à atteindre l’objectif. La correction du biais de publication a réduit le bénéfice estimé. Les méthodes et les objectifs variaient. Ces données psychologiques concernent un ensemble de techniques de planification. Il ne prouve ni récompense religieuse, ni efficacité de la prière, ni validité de la liste proposée ici. [F19]","ODA adapte cette idée : nomme un geste utile, un moment reconnaissable pour commencer, un lieu adapté et quoi faire en cas d’obstacle. Choisis une promesse du quotidien qui compte dans ta semaine. Garde-la au fil du cours. Les leçons suivantes t’aident à ajuster la préparation, reconnaître l’aide reçue ou demander du soutien si nécessaire. Avoir plusieurs motivations ne t’oblige pas à les dévoiler. Tu peux garder ton plan privé. ODA retient alors ton choix de retour, mais ne peut retrouver des détails que tu ne lui as jamais confiés."]}],sourceIds:["F01","F02","F19"]}},{schemaVersion:2,revision:2,id:"faith-2",courseId:"faith",locale:"fr",title:"Tu vérifies encore ? Tiens ta promesse.",goal:"Tiens ta promesse si tout est prêt. Sinon, comble un manque précis et fixe quand arrêter.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Tout est prêt, mais tu vérifies encore ? Une nouvelle vérification doit combler un vrai manque.",reason:{id:"faith-2-actual-gap-cost",label:"Que manque-t-il, ou que retarderait une nouvelle vérification ?",kind:"text",maxLength:160,optional:!0,suggestions:["Tout est prêt : tenir ma promesse","Information manquante : vérifier ce point","Horaire incertain : se mettre d’accord"]},why:{id:"faith-2-why",label:"Quelle préparation suffit pour ton prochain geste concret ?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Al Imran 3:159 réunit consultation, résolution et confiance en Dieu. ODA en tire une réflexion pratique, sans imposer que la confiance commence seulement après la préparation. Prendre ta part au sérieux ne rend pas le résultat certain.","Reviens à ta promesse. Un vrai manque ? Choisis une préparation utile et fixe quand arrêter. Tout est prêt ? Agis. Note ce que tu as terminé, sans attendre d’être rassuré. La prière peut accompagner ce choix en privé. Elle reste facultative et ne garantit aucun résultat."],example:{title:"Youssef vérifie une fois",text:"La voisine de Youssef demande si le guide convient à son téléphone. À la table de cuisine, il vérifie une étape et la corrige. Il termine le test prévu et propose un appel pour demain, sans risque. Rien n’est confirmé. Il note la préparation terminée, garde sa prière privée et ne compte pas l’appel futur comme fait."}},move:{invitation:"Prêt ? Tiens ta promesse. Sinon, prépare un point précis et fixe quand arrêter.",instructions:["Garde ta promesse. « Adapter ce geste », puis « Préparation » : seulement pour un manque précis.","Précise quand arrêter et l’utilisation suivante, confirmée ou non.","Prévois seulement la préparation. Confirme séparément quand agir dans ton calendrier."],prompts:[{id:"faith-2-gap-next-use",label:"Quel manque combler, quand arrêter, et l’utilisation suivante est-elle confirmée ?",kind:"text",maxLength:160,optional:!0,visible:!0,help:"Exemple : contacts testés une fois ; appel incertain. Date et repère privés ou dans l’action."}],suggestions:{action:["Exemple : envoyer à Camille le lien convenu prêt","Faire l’appel convenu avec Camille pour son téléphone"],minimum:["Envoyer à Camille le lien prêt et convenu","Expliquer comment appeler le premier contact convenu"],cue:["Après mon déjeuner","Au début de l’appel confirmé à 18 h"],place:["Dans notre conversation par SMS","Dans notre appel habituel et accessible"],minutes:[2,5],fallback:["Utiliser le mail convenu si le SMS échoue","Si Camille est indisponible, demander une autre date"],observation:["Lien envoyé ; vérifications répétées ou information nouvelle","Appel tenté ; une autre date peut rester incertaine"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}],bundles:[{action:"Exemple : envoyer à Camille le lien convenu prêt",minimum:"Envoyer à Camille le lien prêt et convenu",cue:"Après mon déjeuner",place:"Dans notre conversation par SMS",fallback:"Utiliser le mail convenu si le SMS échoue",observation:"Lien envoyé ; vérifications répétées ou information nouvelle",minutes:2},{action:"Faire l’appel convenu avec Camille pour son téléphone",minimum:"Expliquer comment appeler le premier contact convenu",cue:"Au début de l’appel confirmé à 18 h",place:"Dans notre appel habituel et accessible",fallback:"Si Camille est indisponible, demander une autre date",observation:"Appel tenté ; une autre date peut rester incertaine",minutes:5}]},suggested:{action:"Exemple : envoyer à Camille le lien convenu prêt",minimum:"Envoyer à Camille le lien prêt et convenu",minutes:2,cueHint:"Après mon déjeuner",placeHint:"Dans notre conversation par SMS",obstacleHint:"Exemple : aucune information ne manque ; je veux une certitude",fallbackHint:"Utiliser le mail convenu si le SMS échoue",observationHint:"Lien envoyé ; vérifications répétées ou information nouvelle"},stopRule:"Arrête à ta limite. Détresse perturbant le quotidien ? Demande des soins maintenant.",accessibleAlternative:"Répétition ou conseil accessible. Prière et écriture restent facultatives."},result:{question:"As-tu accompli exactement le geste que tu avais enregistré ?",observationPrompt:"Qu’as-tu fait ou préparé ? Quelle utilisation reste à confirmer ?"},judgment:{primary:{id:"faith-2-decision",scenario:"Youssef a testé les instructions et confirmé l’heure de l’appel. Il vérifie encore les mêmes étapes, car il craint toujours que l’appel se passe mal.",question:"Quel choix répond au besoin qui reste ?",options:[{id:"longer-test",text:"Refaire un test complet des mêmes instructions pour se sentir plus sûr avant l’appel prévu.",feedback:"Un nouveau test peut aider si un point précis manque. Ici, les étapes sont vérifiées et l’horaire confirmé. Répéter ne garantit pas l’appel. Garde l’occasion convenue pour passer à l’action."},{id:"cancel-call",text:"Remplacer l’appel de demain par un autre guide écrit, pour pouvoir préparer sans avoir de conversation en direct.",feedback:"Un guide écrit peut être une solution accessible si nécessaire. Ici, l’appel convenu est prêt et adapté. Changer de format uniquement pour chercher une certitude évite un prochain geste déjà faisable."},{id:"keep-opportunity",text:"Terminer cette préparation, maintenir l’appel convenu pour demain et accepter que le résultat reste incertain.",feedback:"Ce choix garde la préparation utile et sa limite, sans prétendre garantir le résultat. Youssef note ce qui est prêt et tente l’appel au moment convenu. L’action ne dépend pas d’une baisse d’anxiété."}],bestOptionId:"keep-opportunity"}},carry:{takeaway:"Fais ce qui dépend de toi. Laisse le résultat ouvert et précise la prochaine occasion.",followUp:{questionId:"faith-2-gap-execution-return",question:"Le geste enregistré a-t-il eu lieu ? La préparation répondait-elle à un vrai manque ?",observationPrompt:"Qu’as-tu fait ou préparé ? Quelle utilisation reste à confirmer ?",adjustmentPrompt:"Que changer pour que le prochain essai te convienne ?"}},goDeeper:{sections:[{heading:"Effort et confiance sans ordre imposé",paragraphs:["Al Imran 3:159 réunit la consultation, la résolution et la confiance en Dieu. ODA en tire une démarche pratique facultative : poser une question sur un manque réel, faire un choix réfléchi et accomplir la partie qui est à ta portée. C’est une interprétation pour le quotidien. Elle ne dit pas que la confiance est absente tant qu’une liste de préparatifs reste incomplète. Elle ne promet pas non plus le résultat demandé. [F03]","Cet exercice ne prescrit pas comment faire confiance. La limite concerne ta préparation quotidienne. À toi de choisir si cette réflexion religieuse facultative t’aide à décider. Une question, une instruction vérifiée ou une répétition peuvent suffire. Arrête à la limite choisie. Confirme ensuite, séparément dans ton calendrier, la date et le moment où tu agiras, ou indique qu’ils restent incertains. Enregistrer une préparation prévoit celle-ci et son bilan du lendemain ; cela ne programme pas l’appel ultérieur. Un appel prévu n’est pas un appel effectué. Une prière volontaire peut accompagner les deux étapes et rester privée. Il n’y a ni quantité de pratique religieuse prescrite ni score de foi."]},{heading:"Choisir une préparation suffisante",paragraphs:["Les recherches sur les plans face aux obstacles soutiennent, en moyenne, l’intérêt de plans concrets pour atteindre des objectifs dans des contextes variés. Elles ne testent pas ce cadre religieux. Elles ne prouvent ni que deux minutes sont optimales, ni que vérifier pour se rassurer améliore le résultat. [F19] La limite proposée par ODA est une adaptation pour garder la préparation liée à un besoin réel. Il manque une information ? Cherche-la. L’étape suivante est dangereuse ou inaccessible ? Choisis un autre moyen ou un soutien adapté.","Si la détresse, le sommeil perturbé ou les difficultés quotidiennes persistent, un soutien professionnel peut accompagner la réflexion religieuse. Les conseils du NIMH n’établissent pas de cause spirituelle et n’imposent pas d’attendre deux semaines pour demander de l’aide. Une crise demande un soutien immédiat, pas un exercice de préparation supplémentaire. [F20] Une personne compétente en matière religieuse peut offrir un conseil spirituel facultatif, mais ne remplace pas les soins. Note la préparation réellement faite. Tu n’as pas besoin d’une certitude émotionnelle ou d’une réussite extérieure pour la considérer comme terminée."]}],sourceIds:["F03","F19","F20"]}},{schemaVersion:2,revision:2,id:"faith-3",courseId:"faith",locale:"fr",title:"On t’a aidé. Dis précisément comment.",goal:"Écris un remerciement sincère pour l’aide reçue dans ton engagement. Le partager reste facultatif.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Aide reçue malgré un désaccord ? Remercie sans prétendre que tout va bien.",reason:{id:"faith-3-acknowledgment-tradeoff",label:"Qu’est-ce qui rend le merci difficile ? Quelle aide peux-tu reconnaître honnêtement ?",kind:"text",maxLength:160,optional:!0,suggestions:["Reconnaître l’aide sans régler le désaccord","Garder le contact sûr et facultatif","Sans aide reçue, poursuivre ma promesse"]},why:{id:"faith-3-why",label:"Quelle aide sans risque t’a permis d’avancer dans ta promesse ?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Abu Dawud 4811 relie le remerciement des autres à celui d’Allah. Ce petit mot est une adaptation d’ODA. Nomme une aide réelle apportée à ta promesse, sans embellir toute la relation.","La gratitude exprimée a un petit bénéfice moyen sur le bien-être, variable selon les études. Cela ne prouve aucune équivalence aux thérapies et n’exige aucun mieux-être. Note le geste et son bénéfice en privé. Ta promesse inachevée reste distincte. Écrire et envoyer volontairement sont deux actions. Sans aide reçue, poursuis ta promesse."],example:{title:"Le mot sincère de Youssef",text:"Sa sœur a prêté à Youssef un guide téléphonique. Un autre désaccord familial persiste. Il écrit en privé : « Ton guide m’a aidé à expliquer le premier appel à notre voisine. » Hésitant à reprendre contact, il garde le mot ce soir. Il note seulement l’écriture dans ODA, sans dévoiler le contenu. Le désaccord reste."}},move:{invitation:"Nomme l’aide reçue. Ce mot reste distinct de ta promesse.",instructions:["Choisis « Prévoir un geste lié distinct ». Ta promesse inachevée reste à part.","Nomme le geste et son bénéfice. Partage seulement si le contact est sûr et souhaité.","Sans aide, poursuis ta promesse. Sous pression, reconnais seulement cette aide ou fais une pause."],prompts:[],suggestions:{action:["Exemple : remercier Camille en privé pour son guide","Remercier Alex en privé pour son remplacement mardi"],minimum:["Écrire : son guide a facilité l’explication d’un appel","Écrire : son remplacement a permis mon rendez-vous convenu"],cue:["Après mon déjeuner","À la fin du service convenu"],place:["Dans mes notes personnelles","Dans un endroit calme, privé et accessible"],minutes:[2,1],fallback:["Dire seulement le geste et son bénéfice, seul","Évoquer seulement ce service ; laisser le désaccord ouvert"],observation:["Mot écrit ou dit ; promesse initiale en attente","Merci exprimé ; promesse initiale toujours distincte"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}],bundles:[{action:"Exemple : remercier Camille en privé pour son guide",minimum:"Écrire : son guide a facilité l’explication d’un appel",cue:"Après mon déjeuner",place:"Dans mes notes personnelles",fallback:"Dire seulement le geste et son bénéfice, seul",observation:"Mot écrit ou dit ; promesse initiale en attente",minutes:2},{action:"Remercier Alex en privé pour son remplacement mardi",minimum:"Écrire : son remplacement a permis mon rendez-vous convenu",cue:"À la fin du service convenu",place:"Dans un endroit calme, privé et accessible",fallback:"Évoquer seulement ce service ; laisser le désaccord ouvert",observation:"Merci exprimé ; promesse initiale toujours distincte",minutes:1}]},suggested:{action:"Exemple : remercier Camille en privé pour son guide",minimum:"Écrire : son guide a facilité l’explication d’un appel",minutes:2,cueHint:"Après mon déjeuner",placeHint:"Dans mes notes personnelles",obstacleHint:"Exemple : me sentir obligé de régler notre désaccord",fallbackHint:"Dire seulement le geste et son bénéfice, seul",observationHint:"Mot écrit ou dit ; promesse initiale en attente"},stopRule:"Ne contacte personne au risque de ta sécurité. Remercier ne doit pas effacer un tort subi.",accessibleAlternative:"Parle ou écris en privé ; dévoiler la personne et le contenu reste facultatif."},result:{question:"As-tu exprimé le remerciement choisi ?",observationPrompt:"L’as-tu écrit, dit en privé ou partagé par choix ?"},judgment:{primary:{id:"faith-3-honest-acknowledgment-decision",scenario:"Alex a remplacé Youssef mardi, lui permettant d’aller à un rendez-vous de soins. Leur autre désaccord persiste. Le contact est sûr. Alex a dit ne pas pouvoir le remplacer la semaine prochaine et ne pas vouloir de nouvelle demande maintenant. Youssef veut le remercier pour mardi.",question:"Quel merci respecte les faits et la limite posée par Alex ?",options:[{id:"faith-3-misstated-help",text:"Remercier Alex d’avoir organisé le rendez-vous de soins et assuré son service mardi pour qu’il puisse y aller.",feedback:"Alex a remplacé Youssef ; rien n’indique qu’il a organisé le rendez-vous. Remercie pour les faits observés. Le désaccord peut rester ouvert."},{id:"faith-3-specific-thanks",text:"Remercier Alex pour le remplacement mardi et le rendez-vous rendu possible, sans prétendre résoudre leur désaccord.",feedback:"Ce choix nomme l’aide et son bénéfice en respectant la limite. Tu peux partager ou garder le mot. Tes sentiments peuvent rester mêlés. Ni la promesse ni le désaccord ne sont réglés."},{id:"faith-3-new-request",text:"Remercier Alex pour mardi et expliquer pourquoi un autre remplacement la semaine prochaine l’aiderait aussi.",feedback:"Alex a refusé une nouvelle demande maintenant. L’ajouter ignore sa limite. Remercie pour mardi et cherche ailleurs le prochain remplacement. Merci et demande peuvent coexister."}],bestOptionId:"faith-3-specific-thanks"}},carry:{takeaway:"Reconnais l’aide reçue. Un mot ne tient pas ta promesse initiale et ne règle pas toute blessure.",followUp:{questionId:"faith-3-related-note-return",question:"Le merci était-il sincère et sûr ? Ta promesse initiale est-elle restée enregistrée séparément ?",observationPrompt:"Mot écrit, dit ou partagé ? Quelle action promise reste à faire ?",adjustmentPrompt:"Que changer pour que le prochain essai te convienne ?"}},goDeeper:{sections:[{heading:"Le mot précis est une adaptation",paragraphs:["Abu Dawud 4811 relie le remerciement des autres à celui d’Allah. La fiche attribue le récit à Abu Hurayrah et affiche une classification sahih par al-Albani. Le mot d’ODA est une adaptation. Ce n’est ni le texte de cette source ni une nouvelle authentification religieuse. [F07] Tu peux reconnaître une contribution sans partager ta réflexion religieuse privée ni laisser l’application juger ta gratitude.","Le modèle nomme ce que la personne a fait et le bénéfice observé. C’est une aide à l’écriture. Il ne prétend pas qu’un merci précis est scientifiquement supérieur à un merci général. L’aide reçue d’une personne sûre peut être réelle, tout comme le désaccord ou la blessure qui demeure. Garde ces faits distincts. Écrire en privé et envoyer un message sont deux actions différentes. Note celle que tu as choisie. Un mot privé n’est pas un exercice de gratitude remis à son destinataire. Et un message sans réponse n’annule pas le geste que tu as accompli."]},{heading:"Un petit effet moyen, sans équivalence aux thérapies",paragraphs:["La synthèse de 2023 sur la gratitude exprimée portait sur 23 études et 25 échantillons. Face à des conditions neutres, l’effet moyen sur le bien-être était petit : g = .22, avec un intervalle de confiance à 95 % de .11 à .33. Face à d’autres activités de bien-être, l’intervalle de la différence incluait zéro. Ces activités n’étaient pas forcément des traitements cliniques établis. L’absence de supériorité statistiquement significative ne démontre pas une équivalence aux thérapies. Les totaux de participants, incohérents dans l’article, ne sont pas repris. [F14]","Une synthèse plus vaste de 2025 trouvait aussi un petit bénéfice moyen. Mais son intervalle de prédiction pour une future étude incluait zéro. Les résultats variaient selon les méthodes et les contextes. [F15] Aucune des deux synthèses ne prouve un enseignement religieux, ne garantit un bénéfice personnel ni ne valide cette phrase privée unique. Tu peux terminer le geste sans émotion positive. Utilise ce mot s’il sert la relation ou la direction de vie choisie. Change ou arrête la pratique si elle te semble inutile ou imposée."]}],sourceIds:["F07","F14","F15"]}},{schemaVersion:2,revision:2,id:"faith-4",courseId:"faith",locale:"fr",title:"Tout à porter ? Demande une aide précise.",goal:"Demande une aide précise et sûre, avec un recours si personne n’est disponible.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"Tu portes tout seul ? Demande une aide précise, sans y voir un jugement sur ta foi.",reason:{id:"faith-4-request-boundary-cost",label:"Qu’est-ce qui freine une demande sûre ? Quelle limite la rendrait possible ?",kind:"text",maxLength:160,optional:!0,suggestions:["Demander une tâche bien définie","Limiter les détails privés partagés","Recevoir des soins sans devoir produire"]},why:{id:"faith-4-why",label:"Quelle aide rendrait la poursuite de ta promesse plus sûre ?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Al-Sharh évoque la facilité aux côtés de l’épreuve : un espoir religieux, sans délai garanti. Pense au prochain moment accessible. Prendre soin de toi peut suffire. Demander du soutien laisse ta promesse inachevée distincte.","Les recherches montrent des associations, pas qu’une pratique spirituelle soulage ou qu’une difficulté révèle une foi faible. Demande une aide à une personne sûre ou un professionnel. Sinon, choisis un autre moyen adapté. Demander est ton action ; leur disponibilité, un résultat. Doutes privés et pratiques religieuses n’ont pas de score."],example:{title:"Youssef cherche une autre aide",text:"Épuisé après l’aide à un proche, Youssef ne peut appeler sa voisine ce soir. Son frère ne peut reprendre la tâche ménagère. Youssef contacte un autre parent de confiance et propose à sa voisine un appel ultérieur. L’aide reste incertaine. Il note sa demande et se repose si possible, sans juger sa foi."}},move:{invitation:"Aide courante : demande précisément à une personne sûre.",instructions:["Besoin urgent : cherche une aide de crise ou les urgences avant de programmer un essai.","« Prévoir un geste lié distinct » : précise l’aide, pour qui, comment et quand.","Refus ? Cherche une autre aide sûre et disponible. Ta promesse reste distincte."],prompts:[],suggestions:{action:["Exemple : texto à Camille pour la vaisselle","Appeler le centre de santé : créneaux disponibles"],minimum:["Demander la vaisselle à Camille pour 19 h","Demander au centre de santé un rendez-vous adapté"],cue:["Après le relais convenu à 18 h","À l’ouverture du standard du centre de santé"],place:["Dans notre conversation par SMS","Dans mon espace privé et accessible pour téléphoner"],minutes:[2,5],fallback:["Si refus : vaisselle non indispensable reportée, repos","Utiliser le moyen de réservation accessible du centre"],observation:["Demande envoyée ; aide reçue à vérifier séparément","Contact pris ; rendez-vous peut-être encore à confirmer"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}],bundles:[{action:"Exemple : texto à Camille pour la vaisselle",minimum:"Demander la vaisselle à Camille pour 19 h",cue:"Après le relais convenu à 18 h",place:"Dans notre conversation par SMS",fallback:"Si refus : vaisselle non indispensable reportée, repos",observation:"Demande envoyée ; aide reçue à vérifier séparément",minutes:2,kind:"support"},{action:"Appeler le centre de santé : créneaux disponibles",minimum:"Demander au centre de santé un rendez-vous adapté",cue:"À l’ouverture du standard du centre de santé",place:"Dans mon espace privé et accessible pour téléphoner",fallback:"Utiliser le moyen de réservation accessible du centre",observation:"Contact pris ; rendez-vous peut-être encore à confirmer",minutes:5,kind:"support"}]},suggested:{kind:"support",action:"Exemple : texto à Camille pour la vaisselle",minimum:"Demander la vaisselle à Camille pour 19 h",minutes:2,cueHint:"Après le relais convenu à 18 h",placeHint:"Dans notre conversation par SMS",obstacleHint:"Exemple : la première personne ne peut aider ce soir",fallbackHint:"Si refus : vaisselle non indispensable reportée, repos",observationHint:"Demande envoyée ; aide reçue à vérifier séparément"},stopRule:"Crise ou pensées de te faire du mal : contacte immédiatement un service de crise local. Danger immédiat : appelle les urgences avant de planifier.",accessibleAlternative:"Choisis un moyen accessible. La prière ne remplace jamais les soins nécessaires."},result:{question:"As-tu demandé l’aide ou pris soin de toi ?",observationPrompt:"Qu’as-tu reçu ou fait ? Quel besoin reste insatisfait ?"},judgment:{primary:{id:"faith-4-available-care-decision",scenario:"Leïla doit déplacer son proche dépendant ce soir. Seule, c’est dangereux. Il attend assis en sécurité. Un parent a refusé. Une permanence ouverte peut envoyer quelqu’un ce soir ; les mails sont traités demain. Leïla peut attendre sans risque en appelant.",question:"Quelle demande répond le plus directement au besoin de ce soir ?",options:[{id:"faith-4-staffed-line",text:"Appeler la permanence pour demander l’aide au déplacement ce soir, en laissant son proche assis en sécurité pendant l’attente.",feedback:"La demande vise la tâche et l’aide disponible ce soir. Appeler ne confirme pas l’aide. Si la sécurité change, cherche immédiatement les secours adaptés."},{id:"faith-4-general-call",text:"Appeler la permanence, décrire sa semaine épuisante et demander quels soutiens généraux elle propose aux proches aidants.",feedback:"Parler de la semaine peut aider pour la suite. Mais le déplacement ne peut attendre. Demande-le d’abord ; aborde le soutien durable si temps et sécurité le permettent."},{id:"faith-4-email-and-wait",text:"Envoyer par mail la demande précise et laisser son proche assis en sécurité jusqu’à la réponse courante de demain.",feedback:"Le mail évite un déplacement dangereux, mais la réponse de demain arrive trop tard. Appelle la permanence maintenant et vérifie si une aide adaptée est confirmée."}],bestOptionId:"faith-4-staffed-line"}},carry:{takeaway:"Demander clairement est ton action. La disponibilité du soutien reste à vérifier et à suivre.",followUp:{questionId:"faith-4-related-support-return",question:"As-tu demandé l’aide ? Était-elle disponible ? Quel besoin reste sans réponse ?",observationPrompt:"Quelle demande ou aide a eu lieu ? Quelle promesse initiale reste à part ?",adjustmentPrompt:"Que changer pour que le prochain essai te convienne ?"}},goDeeper:{sections:[{heading:"L’espoir peut accompagner une aide concrète",paragraphs:["Al-Sharh 94:5–6 offre une source d’espoir religieux par la facilité aux côtés de l’épreuve. Aucune garantie que ta difficulté finisse aujourd’hui, à une date choisie ou comme tu le souhaites. La demande de soutien d’ODA est une adaptation pratique. Ce n’est ni un avis religieux ni un effet clinique déduit des versets. [F08] Tu peux réfléchir en privé ou simplement choisir de prendre soin de toi.","Un moment à ta portée peut être bien plus court qu’une journée. Nomme le besoin immédiat. Quelle personne sûre ou quel service pourrait y répondre ? Un premier contact indisponible te renseigne sur ce contact. Cela ne prouve pas que tu dois tout porter seul. Le repos ou les soins professionnels peuvent être toute l’action choisie. Tu n’as pas à produire pour les mériter. Poser une limite peut mieux te protéger qu’une nouvelle promesse. La patience, la gratitude ou le pardon ne doivent jamais servir de consigne pour supporter des violences ou un contact dangereux."]},{heading:"Les catégories de recherche ne jugent pas ta foi",paragraphs:["La synthèse sur le recours à la religion réunissait 49 études et 13 512 participants. Les données étaient surtout observationnelles et autodéclarées. Les valeurs .33 et .22 sont des z de Fisher combinés, pas des corrélations brutes. Parmi les 8 115 participants d’affiliation connue, 57 % étaient protestants et 28 % catholiques. Ces proportions ne couvrent pas tous les participants. Les associations ne prouvent ni causalité ni efficacité des pratiques islamiques. Ces catégories de recherche ne doivent pas devenir un verdict sur ta foi. [F13]","Le NIMH recommande une aide professionnelle quand la détresse persiste ou perturbe le quotidien ; tu peux demander plus tôt. La prière ou un conseil spirituel facultatif peuvent accompagner les soins, mais jamais remplacer un traitement nécessaire. Crise ou pensées de se faire du mal demandent une aide immédiate. Aux États-Unis, appelle le 988 ou envoie un SMS ; en cas de danger vital immédiat, appelle les urgences. Ailleurs, utilise les services locaux de crise ou d’urgence. [F20] N’attends ni le résultat d’un cours ni un délai minimal pour chercher des soins urgents."]}],sourceIds:["F08","F13","F20"]}},{schemaVersion:2,revision:2,id:"faith-5",courseId:"faith",locale:"fr",title:"Aide sans manquer à une autre promesse",goal:"Garde l’engagement utile, confirme l’accord. Fixe une date et une limite en minutes.",minutes:{learning:5,suggestedAction:2,review:2},direction:{hook:"L’appel pour aider s’éternise ? Choisis une aide qui tient vraiment dans ta semaine.",reason:{id:"faith-5-purpose-cost",label:"Que limiteras-tu pour pouvoir tenir cette promesse ?",kind:"text",maxLength:160,optional:!0,suggestions:["Aider à la mesure de mes moyens","Protéger une autre promesse existante","Aider utilement sans exiger de merci"]},why:{id:"faith-5-why",label:"Que limiteras-tu pour pouvoir tenir cette promesse ?",kind:"text",maxLength:160,optional:!0}},idea:{paragraphs:["Reviens à ta promesse : qu’as-tu fait, qu’est-ce qui a aidé, à quel prix ? Garde le geste utile et le soutien nécessaire. Le récit d’Aïcha dans Bukhari souligne les petits actes réguliers et la modération. Une série de jours dans l’application ne mesure pas la foi.","Les études trouvent un bénéfice moyen modeste pour le bien-être de celui qui aide. Ni garantie ni permission d’ignorer les limites. Garde le geste utile et vérifie l’accord. Écris sa limite en minutes dans « Action » ou « Minimum ». Date un essai. Tu envisages la répétition ; demain, choisis une prochaine date après le bilan."],example:{title:"Youssef termine à l’heure",text:"Aider à appeler un contact est utile, mais le soir gêne l’aide au proche de Youssef. Sa voisine accepte deux minutes de SMS après le déjeuner samedi. Il envoie les étapes et respecte ce délai. Une question reste. Il note l’aide et la limite tenue. Samedi prochain reste sans accord."}},move:{invitation:"Garde l’aide souhaitée, fixe sa date et sa durée maximale.",instructions:["Garde la promesse initiale. Ajuste-la seulement par accord réfléchi.","Écris la limite dans « Action » ou « Minimum », ou garde les détails hors d’ODA."],prompts:[],suggestions:{action:["Envoyer les étapes à Camille : 2 minutes maximum","Appeler Alex : expliquer un appel, 5 minutes maximum"],minimum:["Envoyer les étapes convenues en 2 minutes maximum","Expliquer l’appel convenu en 5 minutes maximum"],cue:["À la fin du déjeuner convenu","À l’appel confirmé mercredi, 18 h"],place:["Dans notre conversation par SMS","Dans notre appel habituel et accessible"],minutes:[2,5],fallback:["Si besoin, proposer une autre date confirmée","Si besoin, convenir d’une autre occasion distincte"],observation:["Aide convenue envoyée et souhaitée ; deux minutes respectées","Appel expliqué, aide souhaitée ; cinq minutes maximum respectées"],when:[{label:"Aujourd’hui",daysFromToday:0},{label:"Demain",daysFromToday:1}],bundles:[{action:"Envoyer les étapes à Camille : 2 minutes maximum",minimum:"Envoyer les étapes convenues en 2 minutes maximum",cue:"À la fin du déjeuner convenu",place:"Dans notre conversation par SMS",fallback:"Si besoin, proposer une autre date confirmée",observation:"Aide convenue envoyée et souhaitée ; deux minutes respectées",minutes:2},{action:"Appeler Alex : expliquer un appel, 5 minutes maximum",minimum:"Expliquer l’appel convenu en 5 minutes maximum",cue:"À l’appel confirmé mercredi, 18 h",place:"Dans notre appel habituel et accessible",fallback:"Si besoin, convenir d’une autre occasion distincte",observation:"Appel expliqué, aide souhaitée ; cinq minutes maximum respectées",minutes:5}]},suggested:{action:"Envoyer les étapes à Camille : 2 minutes maximum",minimum:"Envoyer les étapes convenues en 2 minutes maximum",minutes:2,cueHint:"À la fin du déjeuner convenu",placeHint:"Dans notre conversation par SMS",obstacleHint:"Exemple : la demande dépasse nos deux minutes convenues",fallbackHint:"Si besoin, proposer une autre date confirmée",observationHint:"Aide convenue envoyée et souhaitée ; deux minutes respectées"},stopRule:"Protège ta santé, ton sommeil, ton argent et tes engagements. Aucun geste ni contact dangereux n’est exigé.",accessibleAlternative:"Choisis une aide accessible, du repos, du soutien ou une limite."},result:{question:"As-tu accompli le geste choisi dans la limite prévue ?",observationPrompt:"L’aide était-elle utile et souhaitée ? As-tu respecté ta limite ?"},judgment:{primary:{id:"faith-5-task-boundary-decision",scenario:"La voisine de Nadia veut savoir appeler un contact avant son rendez-vous jeudi. Mercredi, Nadia a dix minutes libres avant son aide prévue à un proche. La voisine souhaite un appel de dix minutes ; lire des SMS est difficile. Samedi offre vingt minutes, après le rendez-vous.",question:"Quel plan convient à la tâche utile et aux contraintes des deux personnes ?",options:[{id:"faith-5-saturday-call",text:"Proposer l’appel de vingt minutes samedi pour laisser à la voisine plus de temps pour apprendre les étapes.",feedback:"Samedi protège l’aide au proche et permet de pratiquer davantage. Mais le rendez-vous est jeudi. Garde le créneau convenu mercredi ; réserve samedi aux questions ultérieures."},{id:"faith-5-text-steps",text:"Envoyer les étapes par SMS mercredi pour préserver l’aide au proche et laisser des instructions écrites à la voisine.",feedback:"Le SMS préserve le temps et laisse une référence écrite. Mais la voisine lit difficilement les SMS. L’appel court convenu répond ici à son besoin de façon accessible."},{id:"faith-5-ten-minute-call",text:"Consacrer l’appel convenu mercredi au seul contact, annoncer la fin après dix minutes et arrêter avant l’aide au proche.",feedback:"L’appel répond au besoin avant le rendez-vous, par un moyen souhaité et accessible, sans gêner l’aide au proche. Note l’explication et la limite tenue. Une autre question attendra une occasion distincte."}],bestOptionId:"faith-5-ten-minute-call"}},carry:{takeaway:"Garde une aide souhaitée qui tient dans ta semaine. Son utilité et son coût guideront la suite.",followUp:{questionId:"faith-5-bounded-occurrence-return",question:"L’aide convenue était-elle utile et souhaitée ? La limite en minutes a-t-elle protégé tes autres engagements ?",observationPrompt:"Quel geste utile a eu lieu ? Limite respectée ? Autre date confirmée ?",adjustmentPrompt:"Que changer pour que le prochain essai te convienne ?"}},goDeeper:{sections:[{heading:"Régulier ne veut pas dire sans limites",paragraphs:["Dans le récit attribué à Aïcha, Bukhari 6464 souligne les petits actes réguliers et la modération. Le passage complet concerne aussi les actes et le salut. ODA en tire une réflexion pratique facultative sur un geste durable. Un décompte ne juge ni valeur religieuse ni salut. Intention privée, pratique religieuse, occasion manquée ou série de jours dans l’application : rien de cela ne mesure la foi. [F11]","Relis les actions et demandes de soutien que tu as choisi de noter. Quelle partie a servi ton intention ? Combien de temps et d’effort a-t-elle demandé ? Quelle autre promesse a été déplacée ? Garde cette partie sans ajouter de rituel. Envisage un rythme quotidien ou hebdomadaire, mais date une seule occasion réelle. Ce plan prévoit ce geste et son bilan du lendemain, sans répétition automatique. Vérifie l’accord, annonce une limite réaliste et respecte-la. Si le besoin dépasse tes moyens, proposer moins, orienter ailleurs, te reposer ou arrêter peut être plus responsable qu’une aide illimitée. Les mercis et émotions agréables ne conditionnent pas l’action."]},{heading:"Ce que les études sur la bienveillance ont testé",paragraphs:["La synthèse de 2018 sur la bienveillance réunissait 27 études et 4 045 participants. Les gestes bienveillants apportaient un bénéfice moyen modeste au bien-être de celui qui aide, avec des échantillons et méthodes variés. Ni bénéfice garanti pour chaque personne qui donne ou reçoit, ni mesure d’une récompense religieuse, ni validation du sacrifice sans limites. Ne pas détecter de facteurs modérateurs ou de biais de publication ne prouve pas leur absence. [F16]","Dans un autre essai, le groupe d’aide aux autres devait accomplir trois gestes le même jour chaque semaine pendant quatre semaines. Le suivi avait lieu deux semaines après. Pas six semaines de gestes prescrits. Les effectifs du résumé et des groupes répartis aléatoirement différaient ; les analyses principales d’évolution incluaient moins de personnes. [F18] Le geste unique d’ODA, limité à tes moyens, diffère de l’essai. Prévois une prochaine occasion seulement si elle convient. Le bilan de demain vérifie l’utilité, l’accord et le coût. Il n’exige ni répétition aujourd’hui ni série de jours consacrés à la foi."]}],sourceIds:["F11","F16","F18"]}}];function n(e,t,a){return{id:e.id,schemaVersion:2,v2:e,title:e.title,minutes:e.minutes.learning,goal:e.goal,reading:e.idea.paragraphs,deeper:e.goDeeper.sections,example:e.idea.example,practice:[e.move.instructions[0],e.move.instructions[1],"Note ce qui s’est réellement passé et reviens sur ce même essai demain."],reflection:e.direction.reason.label,question:e.judgment.primary.question,options:e.judgment.primary.options.map(s=>s.text),correct:t,feedback:e.judgment.primary.options[t].feedback,takeaway:e.carry.takeaway,sources:e.id==="faith-5"?[...e.goDeeper.sourceIds,"faith-kindness"]:e.goDeeper.sourceIds,photo:a}}const o={id:"faith",title:"Tu veux aider. Tiens une promesse avec ta foi.",subtitle:"5 leçons facultatives. Essaie une promesse qui compte, garde ta réflexion privée et fais place aux soins et aux limites.",description:"Relie une réflexion islamique facultative à un geste du quotidien choisi. Ajuste-le avec une préparation utile, un merci sincère, du soutien et des limites claires.",scope:"Réflexion islamique et pratiques quotidiennes facultatives. Sources religieuses et recherches psychologiques sont présentées séparément. L’anxiété et les difficultés ne sont pas un manque de foi. Ce cours ne constitue pas un avis religieux et ne remplace pas les soins de santé mentale. En crise ou si tu penses te faire du mal, contacte le numéro d’urgence local.",outcome:"Une promesse essayée ou mise en pause, une réflexion privée et une prochaine action ou aide avec une date.",photo:{id:"1767396024869-756a346dc39d",alt:"Une cour de mosquée avec des portes en arc et des arbres"},lang:"fr",lessons:[n(i[0],1,{id:"1778616364918-34490657598f",alt:"Un homme tenant un chapelet de prière"}),n(i[1],2,{id:"1590682680695-43b964a3ae17",alt:"Des mains plantant un jeune plant dans la terre"}),n(i[2],1,{id:"1634906346143-aacbc4c02fec",alt:"Un mot de remerciement sur une table, près de lunettes"}),n(i[3],0,{id:"1570739260082-39a84dae80c8",alt:"Une lanterne allumée sur une table en bois"}),n(i[4],2,{id:"1710092784814-4a6f158913b8",alt:"Une femme donnant une assiette de nourriture à une autre femme"})]},u=Object.freeze(Object.defineProperty({__proto__:null,COURSE:o,LESSONS_V2:i,SOURCES:r},Symbol.toStringTag,{value:"Module"}));export{u as f};
